var i=[{title:`Почніть зі своїх вільних днів`,text:`Оберіть дні, коли ви справді можете тренуватися, перш ніж вибирати складний спліт. З двома днями розклад на все тіло в понеділок і четвер лишає кілька днів відновлення між ними. З трьома просто понеділок, середа та п’ятниця. З чотирма можна розподілити два заняття на верх і два на низ протягом тижня. Це приклади, і інші схеми також працюють.`},{title:`Відновлення між пов’язаними заняттями`,text:`Багатьом початківцям добре підходить приблизно день-два між важкими тренуваннями для одних і тих самих м’язів, особливо поки болючість для них нова. Часто цитовані 48 годин є практичною орієнтиром. Ваша тренувальна історія, зусилля, вибір вправ і сон: усе це змінює, скільки відновлення вам потрібно.`},{title:`Куди ставити важку роботу`,text:`Важкі підйоми та підйоми, що потребують багато навички, краще виконувати, коли ви досить свіжі. Дуже вимогливі нахили, присіди та спринтерські інтервали в дні підряд можуть накопичити непотрібну втому. Легка ходьба чи робота на рухливість можуть іти між силовими днями, і вони не рахуються як ще одне важке тренування.`},{title:`Гнучкий тиждень`,text:`Якщо ви пропустили тренування, перенесіть його на вільний день або продовжуйте з наступного заняття. Не втискайте всю пропущену роботу в один день і не нагромаджуйте важкі заняття для одного руху лише для досягнення тижневого числа. Відстежуйте результативність і втому протягом кількох тижнів. Кожному календарному тижню не потрібен однаковий обсяг.`},{title:`Як це працює в TrainUp`,text:`У Профілі ви задаєте, скільки днів на тиждень тренуєтеся, скільки триває заняття і які дні вам до вподоби, і можете змінити їх будь-коли. На Панелі можна ввімкнути нагадування про тренування на обрані дні та час. Історія показує ваші тренування цього тижня, середнє зусилля та графік за 4 тижні, що допомагає відстежувати втому за тижні.`}];var l=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: рекомендації щодо сили та гнучкості`,url:`https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/`},{label:`NSCA: безпека та основи силових тренувань`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};